p='src/corelib/kernel/qobject_impl.h'
s=open(p).read()
old=s[s.index('    /*\n        Logic to statically'):s.index('}\n\n\nQT_END_NAMESPACE')]
new='''    /*
        Logic to statically generate the array of qMetaTypeId
        ConnectionTypes<FunctionPointer<Signal>::Arguments, Unique>::types() returns an array
        of int that is suitable for the types arguments of the connection functions.
        Calling it registers the argument types with the meta-type system.

        The array only exists if all the types can be used as meta types: either
        they are declared as a metatype (Q_DECLARE_METATYPE, built-in, Q_ENUM, ...)
        or they are complete types for which a QMetaType can be created (QObject
        pointers, gadgets, ...). Unique is used for the completeness check and
        should be a type that is unique to the call site (e.g. the signal's class).
        Otherwise, the function returns nullptr and the types are looked up from
        the signal's QMetaMethod when the signal is first emitted.
    */
    template <typename Unique, typename Arg>
    constexpr bool isConnectionTypeAvailable()
    {
        if constexpr (bool(QMetaTypeId2<Arg>::Defined))
            return true;
        else
            return qTryMetaTypeInterfaceForType<Unique, Arg>() != nullptr;
    }

    template <typename Unique, typename Arg>
    int connectionTypeId()
    {
        if constexpr (bool(QMetaTypeId2<Arg>::Defined))
            return QMetaTypeIdHelper<Arg>::qt_metatype_id();
        else
            return QMetaType(qTryMetaTypeInterfaceForType<Unique, Arg>()).id();
    }

    template <typename ArgList, typename Unique> struct ConnectionTypes;
    template <typename Unique> struct ConnectionTypes<List<>, Unique>
    { static const int *types() { return nullptr; } };
    template <typename... Args, typename Unique> struct ConnectionTypes<List<Args...>, Unique>
    {
        static const int *types()
        {
            if constexpr ((isConnectionTypeAvailable<Unique, Args>() && ...)) {
                static const int t[sizeof...(Args) + 1] = { connectionTypeId<Unique, Args>()..., 0 };
                return t;
            } else {
                return nullptr;
            }
        }
    };
'''
